from functools import cache
from typing import Literal

import numpy as np
import torch
from mne.filter import resample
from braindecode.models import BIOT
from braindecode.models.biot import BIOT_CHANNEL_ORDER

# ALIASES generated by Claude
# Old 10-20 names of electrodes used in the bipolar montage
_ALIASES = {"T3": "T7", "T4": "T8", "T5": "P7", "T6": "P8"}


@cache
def _pretrained_biot(checkpoint: str):
    return BIOT.from_pretrained(f"braindecode/biot-pretrained-{checkpoint}").eval()


def _bipolar_montage(data: np.ndarray, ch_names: list[str], n_derivations: int):
    """
    Conversion and ordering from referenctial EEG into bipolar EEG. The
    checkpoints of BIOT expect bipolar EEG layout.
    """
    index = {}
    for i, ch in enumerate(ch_names):
        name = ch.upper()
        index[_ALIASES.get(name, name)] = i

    pairs = [ch.split("-") for ch in BIOT_CHANNEL_ORDER[:n_derivations]]
    missing = sorted({e for pair in pairs for e in pair if e not in index})
    if missing:
        raise ValueError(f"Electrodes {missing} are needed for BIOT but missing.")
    return np.stack([data[:, index[a]] - data[:, index[b]] for a, b in pairs], axis=1)


def biot_embed(
    data: np.ndarray,
    sfreq: float,
    ch_names: list[str],
    batch_size: int = 64,
    device: str = "cpu",
    checkpoint: (
        Literal["six-datasets-18chs"]
        | Literal["shhs-prest-18chs"]
        | Literal["prest-16chs"]
    ) = "six-datasets-18chs",
):
    """
    Pretrained BIOT embedding of EEG epochs.

    Note: BIOT works on the bipolar TCP montage (FP1-F7, F7-T7, ...) and
    identifies a channel only by its position in the input. The referential
    data is therefore re-referenced to that montage. The 18 channel checkpoints
    additionally use C3-A2 and C4-A1, those are only added if A1 and A2 were
    recorded.

    :param data: (n_trials, n_channels, n_times) in micro V
    :param ch_names: Channel names in the order of the data's channel axis have to
    contain FP1, FP2, F3, F4, F7, F8, C3, C4, T7, T8, P3, P4, P7, P8, O1, O2.
    :param checkpoint: Pretrained weights.
    """
    data = np.asarray(data, dtype=np.float64)
    if data.shape[1] != len(ch_names):
        raise ValueError(
            f"Data has {data.shape[1]} channels but {len(ch_names)} ch_names were given."
        )

    model = _pretrained_biot(checkpoint).to(device)
    upper = {ch.upper() for ch in ch_names}
    n_derivations = model.n_chans if {"A1", "A2"} <= upper else 16
    data = _bipolar_montage(data, ch_names, n_derivations)

    sample_freqency = 200
    if sfreq != sample_freqency:
        data = resample(data, up=sample_freqency, down=sfreq, axis=-1)
    if data.shape[-1] < model.encoder.n_fft:
        raise ValueError("Epochs must be at least 1 s long.")

    q = np.quantile(np.abs(data), q=0.95, axis=-1, keepdims=True)
    data = data / (q + 1e-8)

    embeddings = []
    with torch.no_grad():
        for start in range(0, len(data), batch_size):
            X = torch.as_tensor(
                data[start : start + batch_size], dtype=torch.float32, device=device
            )
            feature = model(X, return_features=True)["features"].cpu().numpy()
            embeddings.append(feature)
    return np.concatenate(embeddings)
